package cpupmu

import "strings"

// resolveEvents maps config PMUEvents names to hardware event specs and whether
// uncore/IMC memory bandwidth should be opened.
func resolveEvents(names []string) (core []EventSpec, wantUncore bool) {
	if len(names) == 0 {
		names = []string{"instructions", "cycles"}
	}
	seen := make(map[string]bool)
	for _, raw := range names {
		n := strings.ToLower(strings.TrimSpace(raw))
		if n == "" || seen[n] {
			continue
		}
		seen[n] = true
		switch {
		case n == "instructions" || n == "hw.cpu.instructions":
			core = append(core, EventSpec{Name: "instructions"})
		case n == "cycles" || n == "cpu_cycles" || n == "hw.cpu.cycles":
			core = append(core, EventSpec{Name: "cycles"})
		case strings.Contains(n, "memory_bandwidth") || n == "uncore" || strings.Contains(n, "memory.bandwidth") || n == "memory.io":
			wantUncore = true
		case strings.Contains(n, "cache"):
			core = append(core, cacheSpecsFor(n)...)
		case strings.Contains(n, "tlb"):
			core = append(core, tlbSpecsFor(n)...)
		case strings.Contains(n, "branch"):
			core = append(core, branchSpecsFor(n)...)
		}
	}
	return core, wantUncore
}

func cacheSpecsFor(n string) []EventSpec {
	level := "ll"
	op := "access"
	switch {
	case strings.Contains(n, "l1i"):
		level = "l1i"
	case strings.Contains(n, "l1d") || strings.Contains(n, "l1"):
		level = "l1d"
	case strings.Contains(n, "l2"):
		level = "l2"
	case strings.Contains(n, "l3") || strings.Contains(n, "ll"):
		level = "ll"
	}
	if strings.Contains(n, "miss") {
		op = "miss"
	}
	if n == "cache" || n == "cache_events" {
		return []EventSpec{
			{Name: "cache", Attrs: map[string]string{"hw.cpu.cache.level": "l1d", "hw.cpu.cache.op": "access"}},
			{Name: "cache", Attrs: map[string]string{"hw.cpu.cache.level": "l1d", "hw.cpu.cache.op": "miss"}},
			{Name: "cache", Attrs: map[string]string{"hw.cpu.cache.level": "ll", "hw.cpu.cache.op": "access"}},
			{Name: "cache", Attrs: map[string]string{"hw.cpu.cache.level": "ll", "hw.cpu.cache.op": "miss"}},
		}
	}
	return []EventSpec{{Name: "cache", Attrs: map[string]string{
		"hw.cpu.cache.level": level,
		"hw.cpu.cache.op":    op,
	}}}
}

func tlbSpecsFor(n string) []EventSpec {
	level := "dtlb"
	op := "miss"
	if strings.Contains(n, "itlb") {
		level = "itlb"
	}
	if strings.Contains(n, "access") {
		op = "access"
	}
	return []EventSpec{{Name: "tlb", Attrs: map[string]string{
		"hw.cpu.tlb.level": level,
		"hw.cpu.tlb.op":    op,
	}}}
}

func branchSpecsFor(n string) []EventSpec {
	if n == "branch" || n == "branch_events" {
		return []EventSpec{
			{Name: "branch", Attrs: map[string]string{"hw.cpu.branch.result": "retired"}},
			{Name: "branch", Attrs: map[string]string{"hw.cpu.branch.result": "mispredicted"}},
		}
	}
	result := "retired"
	if strings.Contains(n, "miss") || strings.Contains(n, "mispred") {
		result = "mispredicted"
	}
	return []EventSpec{{Name: "branch", Attrs: map[string]string{"hw.cpu.branch.result": result}}}
}

//go:build linux && (amd64 || arm64)

package ebpf

import (
	"context"
	"encoding/binary"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"strconv"
	"sync"
	"sync/atomic"
	"syscall"
	"time"

	"github.com/cilium/ebpf"
	"github.com/cilium/ebpf/link"
	"github.com/cilium/ebpf/ringbuf"
	"github.com/cilium/ebpf/rlimit"
)

//go:generate ./tracer.sh

// Tracer manages eBPF programs for CUDA runtime and driver API interception.
type Tracer struct {
	logger  *slog.Logger
	objs    *gpueventObjects
	reader  *ringbuf.Reader
	links   []link.Link
	handler EventHandler
	symbols *SymbolResolver
	running atomic.Bool
	closed  atomic.Bool
	wg      sync.WaitGroup
	dropped atomic.Uint64

	mu               sync.Mutex
	attachedInode    map[string]struct{} // successfully attached, or permanently skipped
	uprobes          map[string]*ebpf.Program
	uretprobes       map[string]*ebpf.Program
	driverUprobes    map[string]*ebpf.Program
	driverUretprobes map[string]*ebpf.Program
	stop             chan struct{}
	runStarted       bool
}

// NewTracer loads eBPF programs and attaches uprobes to CUDA libraries.
// Libraries are discovered from the filesystem and from /proc/*/maps (fleet-friendly
// with host PID visibility). If none are present yet, the tracer still starts and
// periodically rescans so late-starting CUDA workloads are picked up.
func NewTracer(logger *slog.Logger, handler EventHandler) (*Tracer, error) {
	// BPF maps count against RLIMIT_MEMLOCK on kernels < 5.11 (and still can in
	// some container configs). Raise/remove the limit when permitted.
	if err := rlimit.RemoveMemlock(); err != nil {
		logger.Warn("could not raise RLIMIT_MEMLOCK; eBPF map load may fail",
			"error", err,
			"hint", "Docker: --ulimit memlock=-1:-1 (and CAP_BPF/CAP_PERFMON); Kubernetes: add securityContext.ulimits or privileged")
	}

	spec, err := loadGpuevent()
	if err != nil {
		return nil, fmt.Errorf("loading eBPF spec: %w", err)
	}

	objs := new(gpueventObjects)
	if err := spec.LoadAndAssign(objs, &ebpf.CollectionOptions{}); err != nil {
		return nil, fmt.Errorf("%w: loading eBPF objects: %v", ErrUnsupported, err)
	}

	t := &Tracer{
		logger:        logger,
		objs:          objs,
		handler:       handler,
		symbols:       NewSymbolResolver(logger),
		attachedInode: make(map[string]struct{}),
		stop:          make(chan struct{}),
		uprobes: map[string]*ebpf.Program{
			"cudaLaunchKernel":            objs.HandleCudaLaunch,
			"cudaLaunchCooperativeKernel": objs.HandleCudaLaunch,
			"cudaLaunchKernelExC":         objs.HandleCudaLaunchExc,
			"cudaGraphLaunch":             objs.HandleCudaGraphLaunch,
			"__cudaGetKernel":             objs.HandleCudaGetKernelEnter,
			"cudaMalloc":                  objs.HandleCudaMallocEnter,
			"cudaMallocAsync":             objs.HandleCudaMallocEnter,
			"cudaFree":                    objs.HandleCudaFree,
			"cudaMemcpy":                  objs.HandleCudaMemcpyEnter,
			"cudaMemcpyAsync":             objs.HandleCudaMemcpyAsync,
			"cudaStreamSynchronize":       objs.HandleCudaStreamSyncEnter,
			"cudaEventRecord":             objs.HandleCudaEventRecordEnter,
			"cudaEventSynchronize":        objs.HandleCudaEventSyncEnter,
			"cudaSetDevice":               objs.HandleCudaSetDeviceEnter,
		},
		uretprobes: map[string]*ebpf.Program{
			"__cudaGetKernel":       objs.HandleCudaGetKernelExit,
			"cudaMalloc":            objs.HandleCudaMalloc,
			"cudaMallocAsync":       objs.HandleCudaMalloc,
			"cudaMemcpy":            objs.HandleCudaMemcpy,
			"cudaStreamSynchronize": objs.HandleCudaStreamSync,
			"cudaDeviceSynchronize": objs.HandleCudaDeviceSync,
			"cudaEventRecord":       objs.HandleCudaEventRecordExit,
			"cudaEventSynchronize":  objs.HandleCudaEventSyncExit,
			"cudaSetDevice":         objs.HandleCudaSetDevice,
		},
		driverUprobes: map[string]*ebpf.Program{
			"cuLaunchKernel":        objs.HandleCuLaunchKernel,
			"cuLaunchKernel_ptsz":   objs.HandleCuLaunchKernel,
			"cuLaunchKernelEx":      objs.HandleCuLaunchKernelEx,
			"cuLaunchKernelEx_ptsz": objs.HandleCuLaunchKernelEx,
			"cuGraphLaunch":         objs.HandleCuGraphLaunch,
			"cuGraphLaunch_ptsz":    objs.HandleCuGraphLaunch,
			"cuModuleGetFunction":   objs.HandleCuModuleGetFunctionEnter,
			"cuStreamSynchronize":   objs.HandleCudaStreamSyncEnter,
		},
		driverUretprobes: map[string]*ebpf.Program{
			"cuLaunchKernel":        objs.HandleCuLaunchKernelExit,
			"cuLaunchKernel_ptsz":   objs.HandleCuLaunchKernelExit,
			"cuLaunchKernelEx":      objs.HandleCuLaunchKernelExExit,
			"cuLaunchKernelEx_ptsz": objs.HandleCuLaunchKernelExExit,
			"cuGraphLaunch":         objs.HandleCuGraphLaunchExit,
			"cuGraphLaunch_ptsz":    objs.HandleCuGraphLaunchExit,
			"cuModuleGetFunction":   objs.HandleCuModuleGetFunctionExit,
			"cuStreamSynchronize":   objs.HandleCudaStreamSync,
			"cuCtxSynchronize":      objs.HandleCudaDeviceSync,
			"cuMemcpyDtoH":          objs.HandleCudaMemcpy,
			"cuMemcpyHtoD":          objs.HandleCudaMemcpy,
			"cuMemcpyDtoD":          objs.HandleCudaMemcpy,
		},
	}

	n := t.attachNewCudaLibs()
	if n == 0 {
		logger.Info("no CUDA runtime or driver library found yet; rescanning /proc for libcudart and libcuda (Docker --pid=host / Kubernetes hostPID recommended)")
	}

	t.reader, err = ringbuf.NewReader(objs.GpuEvents)
	if err != nil {
		// Do not call Close()/wg.Wait() here — Run has not started. Free BPF objs only.
		t.closed.Store(true)
		close(t.stop)
		objs.Close()
		t.objs = nil
		return nil, fmt.Errorf("%w: creating ring buffer reader: %v", ErrUnsupported, err)
	}

	return t, nil
}

// attachNewCudaLibs discovers libcudart and libcuda and attaches probes.
// Returns the number of libraries newly attached.
func (t *Tracer) attachNewCudaLibs() int {
	if t.closed.Load() {
		return 0
	}
	attached := 0
	for _, cudaLib := range findCudaLibs() {
		if t.attachCudaLib(cudaLib, t.uprobes, t.uretprobes) {
			attached++
		}
	}
	for _, cudaLib := range findCudaDriverLibs() {
		if t.attachCudaLib(cudaLib, t.driverUprobes, t.driverUretprobes) {
			attached++
		}
	}
	t.refreshCudartPIDs()
	t.dropDeadCurrentDevices()
	return attached
}

func (t *Tracer) refreshCudartPIDs() {
	if t.objs == nil || t.objs.CudartPids == nil {
		return
	}
	want := make(map[uint32]struct{})
	one := uint8(1)
	for _, pid := range cudartPIDs() {
		want[pid] = struct{}{}
		p := pid
		_ = t.objs.CudartPids.Put(&p, &one)
	}
	var stale []uint32
	var key uint32
	var val uint8
	iter := t.objs.CudartPids.Iterate()
	for iter.Next(&key, &val) {
		if _, ok := want[key]; !ok {
			stale = append(stale, key)
		}
	}
	for _, pid := range stale {
		p := pid
		_ = t.objs.CudartPids.Delete(&p)
	}
}

func procExists(pid uint32) bool {
	_, err := os.Stat("/proc/" + strconv.FormatUint(uint64(pid), 10))
	return err == nil
}

// dropDeadCurrentDevices removes cuda_current_device entries for exited
// processes. Without this, a reused pid_tgid inherits the previous process's
// CUDA index and fill_header stamps the wrong hw.id.
func (t *Tracer) dropDeadCurrentDevices() {
	if t.closed.Load() || t.objs == nil || t.objs.CudaCurrentDevice == nil {
		return
	}
	var key uint64
	var val int32
	var keys []uint64
	iter := t.objs.CudaCurrentDevice.Iterate()
	for iter.Next(&key, &val) {
		keys = append(keys, key)
	}
	for _, k := range stalePidTgidKeys(keys, procExists) {
		key := k
		_ = t.objs.CudaCurrentDevice.Delete(&key)
	}
}

func (t *Tracer) attachCudaLib(cudaLib string, uprobes, uretprobes map[string]*ebpf.Program) bool {
	if t.closed.Load() {
		return false
	}
	fi, err := os.Stat(cudaLib)
	if err != nil {
		return false
	}
	var key string
	if sys, ok := fi.Sys().(*syscall.Stat_t); ok {
		key = fmt.Sprintf("%d:%d", sys.Dev, sys.Ino)
	} else {
		key = cudaLib
	}

	// Reserve the inode under the lock so concurrent rescans cannot double-attach.
	t.mu.Lock()
	if _, ok := t.attachedInode[key]; ok {
		t.mu.Unlock()
		return false
	}
	t.attachedInode[key] = struct{}{}
	t.mu.Unlock()

	unreserve := func() {
		t.mu.Lock()
		delete(t.attachedInode, key)
		t.mu.Unlock()
	}

	t.logger.Info("attaching CUDA probes", "path", cudaLib)
	ex, err := link.OpenExecutable(cudaLib)
	if err != nil {
		t.logger.Warn("opening CUDA lib failed", "path", cudaLib, "error", err)
		unreserve() // transient (e.g. process exited); allow retry
		return false
	}

	var newLinks []link.Link
	for sym, prog := range uprobes {
		if prog == nil {
			continue
		}
		l, err := ex.Uprobe(sym, prog, nil)
		if err != nil {
			t.logger.Warn("failed to attach uprobe", "symbol", sym, "path", cudaLib, "error", err)
			continue
		}
		newLinks = append(newLinks, l)
		t.logger.Info("attached uprobe", "symbol", sym, "path", cudaLib)
	}
	for sym, prog := range uretprobes {
		if prog == nil {
			continue
		}
		l, err := ex.Uretprobe(sym, prog, nil)
		if err != nil {
			t.logger.Warn("failed to attach uretprobe", "symbol", sym, "path", cudaLib, "error", err)
			continue
		}
		newLinks = append(newLinks, l)
		t.logger.Info("attached uretprobe", "symbol", sym, "path", cudaLib)
	}

	if len(newLinks) == 0 {
		// Keep inode reserved to avoid log spam every rescan on stripped/non-CUDA .so.
		t.logger.Warn("no CUDA symbols attached; skipping further attempts for this library", "path", cudaLib)
		return false
	}

	if t.closed.Load() {
		for _, l := range newLinks {
			l.Close()
		}
		return false
	}

	t.mu.Lock()
	t.links = append(t.links, newLinks...)
	t.mu.Unlock()
	return true
}

func (t *Tracer) hasAttachedProbes() bool {
	t.mu.Lock()
	defer t.mu.Unlock()
	return len(t.links) > 0
}

// cudaRescanInterval keeps discovery snappy until the first attach, then backs
// off so fleet nodes are not full-/proc-scanned every 30s forever.
func cudaRescanInterval(hasProbes bool) time.Duration {
	if hasProbes {
		return 5 * time.Minute
	}
	return 30 * time.Second
}

// Dropped returns approximate count of events that failed ringbuf reserve (not
// directly visible from userspace; reserved for future BPF stats map).
func (t *Tracer) Dropped() uint64 { return t.dropped.Load() }

// Run starts reading events from the ring buffer. Blocks until ctx is cancelled
// or Close is called.
func (t *Tracer) Run(ctx context.Context) {
	t.mu.Lock()
	if t.closed.Load() {
		t.mu.Unlock()
		return
	}
	t.wg.Add(2) // this goroutine + rescan
	t.runStarted = true
	t.running.Store(true)
	t.mu.Unlock()
	defer t.wg.Done()

	go func() {
		defer t.wg.Done()
		// Device-map hygiene stays at 30s so a reused pid_tgid cannot keep a
		// dead process's CUDA index. Full libcudart/libcuda /proc scans still
		// back off after the first attach.
		ticker := time.NewTicker(30 * time.Second)
		defer ticker.Stop()
		var lastAttach time.Time
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.stop:
				return
			case <-ticker.C:
				t.dropDeadCurrentDevices()
				next := cudaRescanInterval(t.hasAttachedProbes())
				if !lastAttach.IsZero() && time.Since(lastAttach) < next {
					continue
				}
				n := t.attachNewCudaLibs()
				lastAttach = time.Now()
				if n > 0 {
					t.logger.Info("attached CUDA probes after /proc rescan", "libraries", n)
				}
			}
		}
	}()

	for {
		select {
		case <-ctx.Done():
			return
		case <-t.stop:
			return
		default:
		}

		record, err := t.reader.Read()
		if err != nil {
			if errors.Is(err, ringbuf.ErrClosed) {
				return
			}
			if t.closed.Load() {
				return
			}
			t.logger.Warn("ring buffer read error", "error", err)
			continue
		}

		t.processRecord(record.RawSample)
	}
}

func (t *Tracer) processRecord(data []byte) {
	if len(data) < 1 {
		return
	}

	eventType := data[0]
	switch eventType {
	case EventTypeKernelLaunch:
		t.processKernelLaunch(data)
	case EventTypeMalloc, EventTypeFree:
		t.processMalloc(data, eventType)
	case EventTypeMemcpy:
		t.processMemcpy(data)
	case EventTypeSync, EventTypeSyncDevice:
		t.processSync(data, eventType == EventTypeSyncDevice)
	case EventTypeSetDevice:
		t.processSetDevice(data)
	case EventTypeGraphLaunch:
		t.processGraphLaunch(data)
	default:
		t.logger.Debug("unknown GPU event type", "type", eventType)
	}
}

func parseHeader(data []byte) (eventMeta, bool) {
	// cuda_event_header_t: type(1)+pad(1)+device_idx(2)+pid(4)+tid(4)+pad(4)+stream(8)+ktime(8) = 32
	if len(data) < 32 {
		return eventMeta{}, false
	}
	return eventMeta{
		PID:       binary.LittleEndian.Uint32(data[4:8]),
		TID:       binary.LittleEndian.Uint32(data[8:12]),
		DeviceIdx: binary.LittleEndian.Uint16(data[2:4]),
		StreamID:  binary.LittleEndian.Uint64(data[16:24]),
		KtimeNs:   binary.LittleEndian.Uint64(data[24:32]),
	}, true
}

func (t *Tracer) processKernelLaunch(data []byte) {
	// header(32) + kern(8) + grid(12) + block(12) + shared(4) + pad(4) = 72
	if len(data) < 72 {
		return
	}
	meta, ok := parseHeader(data)
	if !ok {
		return
	}
	ev := &KernelLaunchEvent{eventMeta: meta}
	ev.KernelAddr = binary.LittleEndian.Uint64(data[32:40])
	ev.GridX = binary.LittleEndian.Uint32(data[40:44])
	ev.GridY = binary.LittleEndian.Uint32(data[44:48])
	ev.GridZ = binary.LittleEndian.Uint32(data[48:52])
	ev.BlockX = binary.LittleEndian.Uint32(data[52:56])
	ev.BlockY = binary.LittleEndian.Uint32(data[56:60])
	ev.BlockZ = binary.LittleEndian.Uint32(data[60:64])
	ev.SharedMemBytes = binary.LittleEndian.Uint32(data[64:68])
	ev.KernelName = t.resolveDriverKernelName(ev.PID, ev.KernelAddr)
	if ev.KernelName == "" {
		ev.KernelName = t.symbols.Resolve(ev.PID, ev.KernelAddr)
	}
	t.handler(ev)
}

func (t *Tracer) resolveDriverKernelName(pid uint32, handle uint64) string {
	if t.objs == nil || t.objs.CuFuncNames == nil || handle == 0 {
		return ""
	}
	key := struct {
		Pid    uint32
		Pad    uint32
		Handle uint64
	}{Pid: pid, Handle: handle}
	var name struct {
		Name [64]byte
	}
	if err := t.objs.CuFuncNames.Lookup(&key, &name); err != nil {
		return ""
	}
	n := 0
	for n < len(name.Name) && name.Name[n] != 0 {
		n++
	}
	if n == 0 {
		return ""
	}
	return string(name.Name[:n])
}

func (t *Tracer) processGraphLaunch(data []byte) {
	meta, ok := parseHeader(data)
	if !ok {
		return
	}
	t.handler(&GraphLaunchEvent{eventMeta: meta})
}

func (t *Tracer) processMalloc(data []byte, typ uint8) {
	if len(data) < 40 {
		return
	}
	meta, ok := parseHeader(data)
	if !ok {
		return
	}
	if typ == EventTypeFree {
		t.handler(&FreeEvent{eventMeta: meta})
		return
	}
	ev := &MallocEvent{eventMeta: meta}
	ev.Size = binary.LittleEndian.Uint64(data[32:40])
	t.handler(ev)
}

func (t *Tracer) processMemcpy(data []byte) {
	if len(data) < 48 {
		return
	}
	meta, ok := parseHeader(data)
	if !ok {
		return
	}
	ev := &MemcpyEvent{eventMeta: meta}
	ev.Size = binary.LittleEndian.Uint64(data[32:40])
	ev.Kind = data[40]
	t.handler(ev)
}

func (t *Tracer) processSync(data []byte, deviceWide bool) {
	meta, ok := parseHeader(data)
	if !ok {
		return
	}
	t.handler(&SyncEvent{eventMeta: meta, DeviceWide: deviceWide})
}

func (t *Tracer) processSetDevice(data []byte) {
	if len(data) < 40 {
		return
	}
	meta, ok := parseHeader(data)
	if !ok {
		return
	}
	ev := &SetDeviceEvent{eventMeta: meta}
	ev.Device = int32(binary.LittleEndian.Uint32(data[32:36]))
	t.handler(ev)
}

// Close detaches all probes and frees resources.
// Safe to call before Run. Callers should cancel the Run context first when active.
func (t *Tracer) Close() {
	t.mu.Lock()
	if t.closed.Load() {
		t.mu.Unlock()
		return
	}
	t.closed.Store(true)
	close(t.stop)
	started := t.runStarted
	t.mu.Unlock()

	if t.reader != nil {
		t.reader.Close()
	}
	if started {
		t.wg.Wait()
	}

	t.mu.Lock()
	links := t.links
	t.links = nil
	t.mu.Unlock()
	for _, l := range links {
		l.Close()
	}
	if t.objs != nil {
		t.objs.Close()
		t.objs = nil
	}
}

import type { ExportResult } from "@opentelemetry/core";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-proto";
import type { ReadableSpan } from "@opentelemetry/sdk-trace-base";

import { convertGenAISpanAttributesToOpenInferenceSpanAttributes } from "../src/index.js";
import { Mutable } from "../src/types.js";

export class OpenInferenceOTLPTraceExporter extends OTLPTraceExporter {
  export(
    spans: ReadableSpan[],
    resultCallback: (result: ExportResult) => void,
  ) {
    const processedSpans = spans.map((span) => {
      const processedAttributes =
        convertGenAISpanAttributesToOpenInferenceSpanAttributes(
          span.attributes,
        );
      // null will be returned in the case of an unexpected error, so we skip the span
      if (!processedAttributes) return span;
      // now we merge the processed attributes with the span attributes
      // optionally you can replace the entire attributes object with the
      // processed attributes if you want _only_ the OpenInference attributes
      (span as Mutable<ReadableSpan>).attributes = {
        ...span.attributes,
        ...processedAttributes,
      };
      return span;
    });

    super.export(processedSpans, resultCallback);
  }
}

package instrumentation

import (
	"os"
	"strconv"
)

// RedactedValue is the placeholder string written in place of any
// attribute value the TraceConfig has marked as hidden. Matches
// Python's openinference.instrumentation.REDACTED_VALUE so a trace
// crossing language boundaries reads the same.
const RedactedValue = "__REDACTED__"

// Environment variable names recognised by TraceConfigFromEnv. They
// match the canonical OPENINFERENCE_HIDE_* names used by the Python
// SDK, so a customer setting OPENINFERENCE_HIDE_INPUTS=true in their
// environment gets the same behavior across Python and Go.
const (
	EnvHideInputs                  = "OPENINFERENCE_HIDE_INPUTS"
	EnvHideOutputs                 = "OPENINFERENCE_HIDE_OUTPUTS"
	EnvHideInputMessages           = "OPENINFERENCE_HIDE_INPUT_MESSAGES"
	EnvHideOutputMessages          = "OPENINFERENCE_HIDE_OUTPUT_MESSAGES"
	EnvHideInputText               = "OPENINFERENCE_HIDE_INPUT_TEXT"
	EnvHideOutputText              = "OPENINFERENCE_HIDE_OUTPUT_TEXT"
	EnvHideLLMInvocationParameters = "OPENINFERENCE_HIDE_LLM_INVOCATION_PARAMETERS"
	EnvHideLLMTools                = "OPENINFERENCE_HIDE_LLM_TOOLS"
	EnvHidePrompts                 = "OPENINFERENCE_HIDE_PROMPTS"
	EnvHideInputImages             = "OPENINFERENCE_HIDE_INPUT_IMAGES"
)

// TraceConfig controls which OpenInference attributes the provider
// instrumentors emit. The zero value emits everything (full fidelity);
// individual flags can be set to suppress specific attribute families
// for PII / sensitive-data protection. Behavior matches Python's
// TraceConfig.mask exactly — see each flag's GoDoc for which keys are
// dropped versus redacted with RedactedValue.
//
// Construct via TraceConfigFromEnv() to pick up the canonical
// OPENINFERENCE_HIDE_* environment variables (matches Python / JS /
// Java behavior), or build directly for in-code overrides.
type TraceConfig struct {
	// HideInputs is the strongest input-side flag. It replaces
	// input.value with RedactedValue and DROPS the entire
	// llm.input_messages.* family (roles, content, names,
	// tool_call_ids, and nested tool_calls) AND drops llm.tools.*
	// (the advertised tool list is considered part of the input).
	// Use this when no input content should leave the process.
	HideInputs bool

	// HideOutputs is the strongest output-side flag. It replaces
	// output.value with RedactedValue and DROPS the entire
	// llm.output_messages.* family (roles, content, and nested
	// tool_calls). llm.finish_reason is metadata and remains visible.
	HideOutputs bool

	// HideInputMessages drops the entire llm.input_messages.*
	// family. input.value, llm.tools.*, and llm.invocation_parameters
	// remain visible — use HideInputs for stricter suppression.
	HideInputMessages bool

	// HideOutputMessages drops the entire llm.output_messages.*
	// family. output.value remains visible — use HideOutputs for
	// stricter suppression.
	HideOutputMessages bool

	// HideInputText keeps llm.input_messages.* structure (roles,
	// indices, tool-call shells) and replaces only the message
	// content field with RedactedValue. For fine-grained control
	// when the message *shape* is useful but the *text* is sensitive.
	HideInputText bool

	// HideOutputText keeps llm.output_messages.* structure and
	// replaces only the message content field with RedactedValue.
	HideOutputText bool

	// HideLLMInvocationParameters omits the llm.invocation_parameters
	// attribute (model temperature/top_p/etc.).
	HideLLMInvocationParameters bool

	// HideLLMTools drops llm.tools.* (the advertised tool list).
	// HideInputs implies this — set HideLLMTools when you want to
	// hide the tool list but keep input messages visible.
	HideLLMTools bool

	// HidePrompts omits the completions-API llm.prompts.* attributes.
	HidePrompts bool

	// HideInputImages omits images from input messages and from the
	// span-level input.images.* attributes. HideInputs also hides them,
	// so call ShouldHideInputImages instead of reading this field directly.
	HideInputImages bool
}

// TraceConfigFromEnv populates a TraceConfig by reading the
// OPENINFERENCE_HIDE_* environment variables. Missing or unparsable
// vars default to false (no hiding). Boolean parsing accepts
// "1"/"true"/"t" (case-insensitive) as true; anything else is false.
//
// Both Middleware and NewTransport call this by default at
// instrumentor construction, so the canonical opt-in path for a
// customer is simply: `export OPENINFERENCE_HIDE_INPUTS=true`.
func TraceConfigFromEnv() TraceConfig {
	return TraceConfig{
		HideInputs:                  envBool(EnvHideInputs),
		HideOutputs:                 envBool(EnvHideOutputs),
		HideInputMessages:           envBool(EnvHideInputMessages),
		HideOutputMessages:          envBool(EnvHideOutputMessages),
		HideInputText:               envBool(EnvHideInputText),
		HideOutputText:              envBool(EnvHideOutputText),
		HideLLMInvocationParameters: envBool(EnvHideLLMInvocationParameters),
		HideLLMTools:                envBool(EnvHideLLMTools),
		HidePrompts:                 envBool(EnvHidePrompts),
		HideInputImages:             envBool(EnvHideInputImages),
	}
}

// MaskInputText returns either the supplied text or RedactedValue,
// depending on whether the config marks input text as hidden.
// Provider instrumentors use this to gate llm.input_messages.{i}.message.content.
func (c TraceConfig) MaskInputText(text string) string {
	if c.HideInputs || c.HideInputText {
		return RedactedValue
	}
	return text
}

// MaskOutputText returns either the supplied text or RedactedValue,
// depending on whether the config marks output text as hidden.
func (c TraceConfig) MaskOutputText(text string) string {
	if c.HideOutputs || c.HideOutputText {
		return RedactedValue
	}
	return text
}

// MaskInputValue returns either the supplied value or RedactedValue,
// depending on whether the config marks the top-level input as hidden.
func (c TraceConfig) MaskInputValue(value string) string {
	if c.HideInputs {
		return RedactedValue
	}
	return value
}

// MaskOutputValue returns either the supplied value or RedactedValue,
// depending on whether the config marks the top-level output as hidden.
func (c TraceConfig) MaskOutputValue(value string) string {
	if c.HideOutputs {
		return RedactedValue
	}
	return value
}

// ShouldHideInputImages reports whether input images should be omitted.
// It covers images inside input messages and the span-level
// input.images.* attributes, and is true when either HideInputs or
// HideInputImages is set.
//
// No Go instrumentor captures images yet. This method exists so that the
// first one to do so honors OPENINFERENCE_HIDE_INPUT_IMAGES, as the other
// language SDKs do.
func (c TraceConfig) ShouldHideInputImages() bool {
	return c.HideInputs || c.HideInputImages
}

// ShouldHideOutputImages reports whether output images should be omitted.
// It covers images inside output messages and the span-level
// output.images.* attributes. There is no dedicated flag for output
// images; they are hidden together with output.value when HideOutputs
// is set.
func (c TraceConfig) ShouldHideOutputImages() bool {
	return c.HideOutputs
}

func envBool(key string) bool {
	v := os.Getenv(key)
	if v == "" {
		return false
	}
	b, err := strconv.ParseBool(v)
	if err != nil {
		return false
	}
	return b
}

package com.databuff.apm.ingest.event;

